using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using YoutubeDl.Engine;
using YoutubeDl.Engine.Discovery;
using YoutubeDl.Engine.Http;
using YoutubeDl.Engine.Providers.Mixcloud;

internal static class MixcloudChecks
{
    internal const string User = "fixture", Slug = "short-song", Other = "second-song", Signed = "?sig=A%2Bb&case=C%2Fd";
    internal static string Media(string kind = "url") => (kind == "url" ? "https://dl.mixcloud.stream/secure/c/m4a/64/3/8/d/9/fixture.m4a" + Signed : kind == "hlsUrl" ? "https://aod.mixcloud.stream/secure/hls/3/8/d/9/fixture.m4a/index.m3u8" : "https://aod.mixcloud.stream/secure/dash2/3/8/d/9/fixture.m4a/manifest.mpd");
    internal static string Encode(string value) { var bytes = Encoding.UTF8.GetBytes(value); var key = Encoding.ASCII.GetBytes("IFYOUWANTTHEARTISTSTOGETPAIDDONOTDOWNLOADFROMMIXCLOUD"); for(var i=0;i<bytes.Length;i++) bytes[i] ^= key[i%key.Length]; return Convert.ToBase64String(bytes); }
    internal static NativeDownloadRequest Request(string directory, bool collection = false) => new() { Url = new(collection ? "https://www.mixcloud.com/fixture/" : "https://www.mixcloud.com/fixture/" + Slug + "/"), OutputDirectory = directory, OutputTemplate = "mixcloud.%(ext)s" };
    internal static JsonNode Show(string slug = Slug, double duration = 2) => new JsonObject { ["key"] = "/fixture/"+slug+"/", ["url"] = "https://www.mixcloud.com/fixture/"+slug+"/", ["slug"] = slug, ["name"] = "Fixture show", ["audio_length"] = duration, ["description"] = "Native clear public audio", ["user"] = new JsonObject { ["username"] = User, ["name"] = "Fixture creator" } };
    internal static JsonNode Playback(string slug = Slug, double duration = 2, string kind = "url") => new JsonObject { ["data"] = new JsonObject { ["cloudcastLookup"] = new JsonObject { ["id"] = "Q2xvdWRjYXN0OjIxODkxMTg0ODE=", ["slug"] = slug, ["name"] = "Fixture show", ["audioLength"] = duration, ["isExclusive"] = false, ["isDisabledCopyright"] = false, ["isExclusivePreviewOnly"] = false,
        ["owner"] = new JsonObject { ["username"] = User }, ["streamInfo"] = new JsonObject { [kind] = Encode(Media(kind)) } } } };
    internal static JsonNode Owner(int count = 2, bool playlist = false) => new JsonObject { ["key"] = playlist ? "/fixture/playlists/set/" : "/fixture/", ["url"] = playlist ? "https://www.mixcloud.com/fixture/playlists/set/" : "https://www.mixcloud.com/fixture/", ["username"] = User, ["name"] = "Fixture collection", ["cloudcast_count"] = count, ["owner"] = new JsonObject { ["username"] = User } };
    internal static JsonNode List(string? next = null, params JsonNode[] shows) => new JsonObject { ["data"] = new JsonArray(shows.Length == 0 ? [Show(),Show(Other)] : shows), ["paging"] = new JsonObject { ["next"] = next } };
    internal static IEnumerable<(string Name, Func<Task> Test)> All => [
        ("Mixcloud public metadata binds requested show owner complete duration and clear source", Facts),
        ("Mixcloud current API and widget aliases retain the same stable show", Aliases),
        ("Mixcloud private repeated manually paged and unsupported feeds remain explicit", Boundaries),
        ("Mixcloud conflicting REST playback owner slug duration and source identities fail", Identities),
        ("Mixcloud exclusive copyright-disabled preview-only DRM-only and malformed data fail", Restrictions),
        ("Mixcloud clear HLS and DASH descriptors retain full audio verification and source URLs", Adaptive),
        ("Mixcloud complete creator pagination binds declared counts source positions and cursors", Pagination),
        ("Mixcloud changed repeated missing premature and oversized collections fail explicitly", Incomplete),
        ("Mixcloud explicit playlists preserve cross-creator and repeated source positions", Playlists),
        ("Mixcloud inspected collections refresh only selected playback descriptors", Snapshots),
        ("Mixcloud known show and selected-child archives skip playback discovery", Archives),
        ("Mixcloud anonymous request identification cancellation denial and redirects remain scoped", Transport)
    ];
    private static async Task Facts()
    { var calls = new List<Uri>(); var page = await Extract(calls); var media = page.Media.Single(); Assert(page.Id == User+"/"+Slug && page.Uploader == "Fixture creator" && page.DurationSeconds==2 && page.AnonymousPlayback && media.Url.AbsoluteUri==Media() && media.IsAudioOnly && media.VerificationDemuxer=="mov" && media.VerificationDurationSeconds==2 && calls.Count==2, "Mixcloud clear source facts changed."); }
    private static async Task Aliases()
    { foreach(var url in new[]{"http://api.mixcloud.com/fixture/short-song/","https://www.mixcloud.com/widget/iframe/?feed=%2Ffixture%2Fshort-song%2F","https://player-widget.mixcloud.com/?feed=%2Ffixture%2Fshort-song%2F&hide_cover=1"}) Assert((await Extract([],request:Request(Path.GetTempPath()) with {Url=new(url)})).Id==User+"/"+Slug,"Widget/API alias changed show identity."); }
    private static Task Boundaries()
    { var provider=new MixcloudProvider();foreach(var url in new[]{"https://secret@www.mixcloud.com/fixture/short-song/","https://www.mixcloud.com:444/fixture/short-song/","https://www.mixcloud.com/fixture/short-song/?access_token=private","https://www.mixcloud.com/fixture/?offset=100","https://player-widget.mixcloud.com/?feed=https%3A%2F%2Fprivate.example%2F","https://www.mixcloud.com/fixture/tracks/","https://www.mixcloud.com/live/fixture/"})Assert(!provider.CanHandle(new(url)),"Unsupported Mixcloud address was claimed.");var registry=YoutubeDl.Engine.Providers.MediaProviderRegistry.CreateDefault();Assert(registry.Resolve(Request(Path.GetTempPath()).Url).Info.Id=="mixcloud"&&!registry.CanHandle(new("https://www.mixcloud.com/fixture/?offset=100")),"Default dispatch bypassed dedicated restrictions.");return Task.CompletedTask; }
    private static async Task Identities()
    { foreach(var change in new Action<JsonNode>[] {r=>r["key"]="/other/short-song/",r=>r["user"]!["username"]="other"}){var rest=Show();change(rest);await Expect<InvalidDataException>(()=>Extract([],rest:rest));}foreach(var change in new Action<JsonNode>[] {g=>g["data"]!["cloudcastLookup"]!["slug"]=Other,g=>g["data"]!["cloudcastLookup"]!["owner"]!["username"]="other",g=>g["data"]!["cloudcastLookup"]!["audioLength"]=20}){var g=Playback();change(g);await Expect<InvalidDataException>(()=>Extract([],playback:g));} }
    private static async Task Restrictions()
    {foreach(var name in new[]{"isExclusive","isDisabledCopyright","isExclusivePreviewOnly"}){var g=Playback();g["data"]!["cloudcastLookup"]![name]=true;await Expect<NotSupportedException>(()=>Extract([],playback:g));}var drm=Playback();drm["data"]!["cloudcastLookup"]!["streamInfo"]=new JsonObject{["hlsDrmUrl"]=Encode(Media("hlsUrl"))};await Expect<NotSupportedException>(()=>Extract([],playback:drm));var bad=Playback();bad["data"]!["cloudcastLookup"]!["streamInfo"]!["url"]="not base64";await Expect<InvalidDataException>(()=>Extract([],playback:bad));var foreign=Playback();foreign["data"]!["cloudcastLookup"]!["streamInfo"]!["url"]=Encode("https://other.example/media.m4a");await Expect<NotSupportedException>(()=>Extract([],playback:foreign));using var malformed=Http([],raw:"bad JSON");await Expect<InvalidDataException>(()=>new MixcloudProvider().ExtractAsync(Request(Path.GetTempPath()),malformed,default));}
    private static async Task Adaptive()
    { foreach(var kind in new[]{"hlsUrl","dashUrl"}){var page=await Extract([],playback:Playback(kind:kind));var media=page.Media.Single();Assert(media.Url.AbsoluteUri==Media(kind)&&media.HasAudio==true&&media.HasVideo==false&&media.VerificationDurationSeconds==2&&media.VerificationDemuxer==(kind=="hlsUrl"?"mpegts":"mov"),"Adaptive clear descriptor lost full source/role verification.");} }
    private static async Task Pagination()
    {var calls=new List<Uri>();var next="https://api.mixcloud.com/fixture/cloudcasts/?limit=100&offset=1";var page=await Extract(calls,request:Request(Path.GetTempPath(),true),first:List(next,Show()),second:List(null,Show(Other)));Assert(page.Entries.Count==2&&page.Entries[1].Position==2&&calls.Count==4&&calls[2].AbsoluteUri==next,"Complete collection cursor/count/source positions changed.");}
    private static async Task Incomplete()
    {foreach(var next in new[]{"https://api.mixcloud.com/other/cloudcasts/?limit=100&offset=1","https://api.mixcloud.com/fixture/cloudcasts/?limit=100&offset=2","https://api.mixcloud.com/fixture/cloudcasts/?limit=100&offset=1&access_token=private"})await Expect<InvalidDataException>(()=>Extract([],request:Request(Path.GetTempPath(),true),first:List(next,Show())));await Expect<InvalidDataException>(()=>Extract([],request:Request(Path.GetTempPath(),true),first:List(null,Show())));await Expect<InvalidDataException>(()=>Extract([],request:Request(Path.GetTempPath(),true),first:List(null,Show(),Show())));await Expect<NotSupportedException>(()=>Extract([],request:Request(Path.GetTempPath(),true) with{MaximumPlaylistEntries=1}));}
    private static async Task Playlists()
    {var request=Request(Path.GetTempPath(),true)with{Url=new("https://www.mixcloud.com/fixture/playlists/set/")};var page=await Extract([],request:request,owner:Owner(2,true),first:List(null,Show(),Show()));Assert(page.Entries.Count==2&&page.Entries[1].Position==2,"Repeated playlist positions were discarded.");}
    private static async Task Snapshots()
    {await Temporary(async directory=>{var calls=new List<Uri>();var engine=new NativeEngine([new MixcloudProvider()],_=>Http(calls));var request=Request(directory,true)with{PlaylistItems="2",SkipDownload=true,WriteInfoJson=true};var info=await engine.InspectAsync(request,default);calls.Clear();var result=await engine.DownloadAsync(request with{PlaylistSnapshot=info.PlaylistSnapshot},null,null,default);Assert(result.Succeeded&&calls.Count==2&&calls[0].AbsolutePath.Contains(Other),"Snapshot result="+result.Succeeded+" calls="+calls.Count+" first="+(calls.FirstOrDefault()?.AbsolutePath??"none")+" failures="+string.Join(";",result.Failures.Select(f=>f.Message)));});}
    private static async Task Archives()
    {await Temporary(async directory=>{var archive=Path.Combine(directory,"archive.txt");await File.WriteAllTextAsync(archive,"mixcloud fixture/short-song\nmixcloud fixture/second-song\n");var calls=new List<Uri>();var engine=new NativeEngine([new MixcloudProvider()],_=>Http(calls));var result=await engine.DownloadAsync(Request(directory)with{DownloadArchiveFile=archive},null,null,default);Assert(result.Skipped&&calls.Count==0,"Known show archive fetched playback.");result=await engine.DownloadAsync(Request(directory,true)with{PlaylistItems="2",DownloadArchiveFile=archive},null,null,default);Assert(result.Succeeded&&calls.Count==3,"Archived selected child fetched playback descriptors.");});}
    private static async Task Transport()
    {var options=new MediaHttpOptions();options.Headers["Authorization"]="Bearer fixture";options.Headers["Cookie"]="fixture=secret";using var http=Http([],options:options,observe:r=>{Assert(!r.Headers.Contains("Authorization")&&!r.Headers.Contains("Cookie"),"Caller credentials reached Mixcloud.");if(r.Method==HttpMethod.Post)Assert(r.Headers.UserAgent.ToString().StartsWith("YoutubeDlModernNative/"),"Playback metadata omitted the app's own identification.");});_=await new MixcloudProvider().ExtractAsync(Request(Path.GetTempPath()),http,default);using var stop=new CancellationTokenSource();stop.Cancel();await Expect<OperationCanceledException>(()=>new MixcloudProvider().ExtractAsync(Request(Path.GetTempPath()),http,stop.Token));using var denied=Http([],status:HttpStatusCode.Forbidden);await Expect<HttpRequestException>(()=>new MixcloudProvider().ExtractAsync(Request(Path.GetTempPath()),denied,default));using var moved=Http([],redirect:true);await Expect<InvalidDataException>(()=>new MixcloudProvider().ExtractAsync(Request(Path.GetTempPath()),moved,default));}
    private static async Task<PageMetadata> Extract(List<Uri> calls,JsonNode? rest=null,JsonNode? playback=null,NativeDownloadRequest? request=null,JsonNode? first=null,JsonNode? second=null,JsonNode? owner=null)
    {using var http=Http(calls,rest,playback,first,second,owner);return await new MixcloudProvider().ExtractAsync(request??Request(Path.GetTempPath()),http,default);}
    internal static MediaHttp Http(List<Uri> calls,JsonNode? rest=null,JsonNode? playback=null,JsonNode? first=null,JsonNode? second=null,JsonNode? owner=null,Func<HttpRequestMessage,HttpResponseMessage>? media=null,MediaHttpOptions? options=null,Action<HttpRequestMessage>? observe=null,string? raw=null,HttpStatusCode status=HttpStatusCode.OK,bool redirect=false)=>new(new Handler(async r=>
    {calls.Add(r.RequestUri!);observe?.Invoke(r);var uri=r.RequestUri!;JsonNode data;if(uri.Host=="www.mixcloud.com"&&uri.AbsolutePath=="/graphql"){var body=JsonNode.Parse(await r.Content!.ReadAsStringAsync())!;var slug=body["variables"]!["lookup"]!["slug"]!.GetValue<string>();data=playback??Playback(slug);}else if(uri.Host=="api.mixcloud.com"){if(uri.AbsolutePath.EndsWith("/cloudcasts/"))data=uri.Query.Contains("offset=1")?second??List(null,Show(Other)):first??List();else if(uri.AbsolutePath is "/fixture/" or "/fixture/playlists/set/")data=owner??Owner(playlist:uri.AbsolutePath.Contains("playlists"));else data=rest??Show(uri.AbsolutePath.Contains(Other)?Other:Slug);}else return media?.Invoke(r)??throw new InvalidOperationException("Unexpected Mixcloud source request.");return new(status){Content=new StringContent(raw??data.ToJsonString()),RequestMessage=redirect?new(HttpMethod.Get,"https://other.example/data"):r};}),options??new());
    private static async Task Temporary(Func<string,Task> test){var directory=Path.Combine(Path.GetTempPath(),"mixcloud-check-"+Guid.NewGuid());Directory.CreateDirectory(directory);try{await test(directory);}finally{Directory.Delete(directory,true);}}
    private static void Assert(bool value,string message){if(!value)throw new InvalidOperationException(message);}
    private static async Task Expect<T>(Func<Task> action)where T:Exception{try{await action();}catch(T){return;}throw new InvalidOperationException("Expected "+typeof(T).Name);}
    private sealed class Handler(Func<HttpRequestMessage,Task<HttpResponseMessage>> run):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){ct.ThrowIfCancellationRequested();return run(request);}}
}
